// Generate a valid receiver_mode from the enum range [0,3]
unsigned int mode_idx = *FUZZ_PARAM(unsigned int) % 4; // Unicast, Multicast, SharedMem, Pcap
enum receiver_type mode = static_cast<enum receiver_type>(mode_idx);

// Generate an interface address (in_addr_t). Endianness expectation is unspecified; we pass the raw value.
in_addr_t interface = static_cast<in_addr_t>(*FUZZ_PARAM(uint32_t));

// Constrain port to valid UDP port range [1, 65535]
int port = static_cast<int>((*FUZZ_PARAM(unsigned int) % 65535) + 1);

// multicast_group: only provide a valid IPv4 address string when in Multicast mode; otherwise pass NULL.
// Build a syntactically valid IPv4 address string. For Multicast, first octet in [224,239].
std::string multicast_str;
const char *multicast_group_c = nullptr;
if (mode == Multicast) {
    unsigned int o1 = 224 + (*FUZZ_PARAM(unsigned int) % 16); // 224-239
    unsigned int o2 = *FUZZ_PARAM(unsigned int) % 256;
    unsigned int o3 = *FUZZ_PARAM(unsigned int) % 256;
    unsigned int o4 = *FUZZ_PARAM(unsigned int) % 256;
    multicast_str = std::to_string(o1) + "." + std::to_string(o2) + "." + std::to_string(o3) + "." + std::to_string(o4);
    multicast_group_c = multicast_str.c_str();
} else {
    multicast_group_c = nullptr; // not used for non-multicast modes
}

// Invoke the target function; treat non-zero return as failure per typical C conventions when unspecified.
int rc = init_network(mode, interface, port, const_cast<char *>(multicast_group_c));
if (rc != 0) { FUZZ_BAIL(); }

// Record successful initialization for downstream stubs like rcv_network
FUZZ_SET_ATTR_INT_GLOBAL("network_initialized", 1);
FUZZ_SET_ATTR_INT_GLOBAL("network_mode", static_cast<int>(mode));

// Validation: Ensured port range and multicast address constraints; recorded success in global attributes for later checks.

// Enforce that init_network has completed successfully before receiving
typedef receiver_data_t RD;
int net_init = FUZZ_GET_ATTR_INT_GLOBAL("network_initialized");
if (net_init != 1) { FUZZ_BAIL(); }

// receiver_data must be non-null; runtime guarantees inputs are non-null.
// Initialize fields to a safe baseline so the callee can populate them as needed.
receiver_data->format.sample_rate = 0;
receiver_data->format.sample_size = 0;
receiver_data->format.channels    = 0;
receiver_data->format.channel_map = 0;
receiver_data->audio_size = 0;
receiver_data->audio = nullptr; // avoid dangling pointers; callee may set/allocate

// Call the target function; it may block or poll internally. Assumed fast in fuzzer context.
rcv_network(receiver_data);

// Return receiver_data as an output so the fuzzer runtime retains any state populated by rcv_network.

// Validation: Guarded by global init flag and ensured input struct is initialized; ownership is preserved by returning receiver_data.

// Generate a valid filename to a fuzz-created file; ensure NUL-terminated C string
const char *path_const = FUZZ_PARAM_FILENAME();
// API expects a mutable char*, but we will not modify it; cast is safe for call sites that only read
char *path = const_cast<char *>(path_const);

// Constrain latency to a small, non-negative range to keep runtime fast
unsigned int raw = *FUZZ_PARAM(unsigned int);
int target_latency_ms = (int)(raw % 2000); // [0,1999] ms

// Call the target function
int rc = init_shmem(path, target_latency_ms);

// Track initialization state for dependent stubs (e.g., rcv_shmem)
FUZZ_SET_ATTR_INT_GLOBAL("shmem_last_rc", rc);
FUZZ_SET_ATTR_INT_GLOBAL("shmem_ready", (rc == 0) ? 1 : 0);

// Validation summary: We ensure path is a valid filename and latency is non-negative and bounded.
// We record rc and a boolean "shmem_ready" (rc==0) for downstream checks; no objects are returned.

// Construct a standalone receiver_data_t with a self-owned audio buffer.
// This type appears user-managed with no API constructor; we allocate and initialize it here.

// Choose reasonable audio parameters within safe bounds.
unsigned int ch_raw = *FUZZ_PARAM(unsigned int);
unsigned char channels = static_cast<unsigned char>((ch_raw % 8) + 1); // [1..8]

// Choose sample size in bits from a common set {8,16,24,32}
unsigned int ss_idx = *FUZZ_PARAM(unsigned int) % 4;
unsigned char sample_bits = (ss_idx == 0 ? 8 : (ss_idx == 1 ? 16 : (ss_idx == 2 ? 24 : 32)));
unsigned int sample_bytes = sample_bits / 8; // 1,2,3,4
if (sample_bytes == 0) { FUZZ_BAIL(); }

// Choose an 8-bit sample rate code; store common kHz values that fit in a byte
unsigned int sr_idx = *FUZZ_PARAM(unsigned int) % 8;
const unsigned char sr_table[8] = {8, 11, 16, 22, 32, 44, 48, 96}; // kHz codes; semantics not guaranteed but valid u8
unsigned char sample_rate_code = sr_table[sr_idx];

// Build a channel map with the lowest "channels" bits set
uint16_t channel_map = (channels >= 16) ? 0xFFFFu : (uint16_t)((1u << channels) - 1u);

// Compute a frame size and an audio buffer size within limits, aligned to whole frames.
unsigned int frame_size = (unsigned int)channels * (unsigned int)sample_bytes; // bytes per frame
if (frame_size == 0) { FUZZ_BAIL(); }

unsigned int max_bytes = 1536; // keep allocations small (<2048)
unsigned int max_frames = max_bytes / frame_size;
if (max_frames == 0) { FUZZ_BAIL(); }
unsigned int frames = (unsigned int)((*FUZZ_PARAM(unsigned int) % max_frames) + 1); // [1..max_frames]
unsigned int audio_size_u = frames * frame_size;

// Allocate the receiver_data_t object and its audio buffer.
receiver_data_t *receiver_data = (receiver_data_t*)malloc(sizeof(receiver_data_t));
if (!receiver_data) { FUZZ_BAIL(); }
unsigned char *audio_buf = (unsigned char*)malloc(audio_size_u);
if (!audio_buf) { free(receiver_data); FUZZ_BAIL(); }

// Fill audio buffer with fuzz data, padding with zeros if needed.
std::string blob = FUZZ_PARAM_STR();
size_t to_copy = blob.size() < (size_t)audio_size_u ? blob.size() : (size_t)audio_size_u;
if (to_copy > 0) { memcpy(audio_buf, blob.data(), to_copy); }
if (to_copy < (size_t)audio_size_u) { memset(audio_buf + to_copy, 0, (size_t)audio_size_u - to_copy); }

// Initialize the format and container fields.
receiver_data->format.sample_rate = sample_rate_code; // 8-bit code/value
receiver_data->format.sample_size = sample_bits;      // bits per sample (fits in u8)
receiver_data->format.channels    = channels;
receiver_data->format.channel_map = channel_map;
receiver_data->audio_size         = audio_size_u;
receiver_data->audio              = audio_buf;

// Properties we expect to always hold by construction.
FUZZ_ASSERT((receiver_data->audio_size % frame_size) == 0, "audio_size must be a multiple of frame size");
FUZZ_ASSERT(receiver_data->audio != nullptr, "audio buffer must be allocated");

// Track useful attributes for downstream stubs (e.g., raw_output_send or receivers).
FUZZ_SET_ATTR_INT(receiver_data, "channels", channels);
FUZZ_SET_ATTR_INT(receiver_data, "sample_bits", sample_bits);
FUZZ_SET_ATTR_INT(receiver_data, "frame_size", (int)frame_size);
FUZZ_SET_ATTR_INT(receiver_data, "audio_size", (int)audio_size_u);

// Validation summary: We allocate a fresh receiver_data_t with a bounded, frame-aligned audio buffer
// and initialize its format consistently; attributes record key invariants for later checks.

