import random
import struct
from typing import List

# We generate contents for a file (arbitrary binary data) that init_shmem is likely to mmap.
# Based on shmheader definition, create a plausible header followed by ring buffer data.
# struct shmheader {
#   uint32_t magic;
#   uint16_t write_idx;
#   uint8_t  offset;
#   uint16_t max_chunks;
#   uint32_t chunk_size;
#   uint8_t  sample_rate;
#   uint8_t  sample_size;
#   uint8_t  channels;
#   uint16_t channel_map;
# } (assume little-endian typical on Linux)
# We keep total file size <= 4096 bytes.

def _pack_header_le(magic: int, write_idx: int, offset: int, max_chunks: int, chunk_size: int,
                    sample_rate_code: int, sample_size_bits: int, channels: int, channel_map: int) -> bytes:
    # Little-endian layout: I H B H I B B B H
    return struct.pack('<IHBHI BBBH'.replace(' ', ''),
                       magic,
                       write_idx & 0xFFFF,
                       offset & 0xFF,
                       max_chunks & 0xFFFF,
                       chunk_size & 0xFFFFFFFF,
                       sample_rate_code & 0xFF,
                       sample_size_bits & 0xFF,
                       channels & 0xFF,
                       channel_map & 0xFFFF)

def _generate_valid_shm_file(rng: random.Random) -> bytes:
    header_size = 4 + 2 + 1 + 2 + 4 + 1 + 1 + 1 + 2  # 18 bytes

    # Choose small ring so data fits comfortably
    max_chunks = rng.choice([4, 8, 16])
    # Choose small chunk sizes (power-of-two-ish) but leave space
    chunk_size = rng.choice([64, 128, 256, 512])

    # Ensure total size <= 4096
    total_data = max_chunks * chunk_size
    while header_size + total_data > 4096:
        if chunk_size > 64:
            chunk_size //= 2
        elif max_chunks > 4:
            max_chunks //= 2
        total_data = max_chunks * chunk_size

    # Sample rate code mapping (not specified). Provide common options; consumer may treat as Hz or code.
    rate_choices = [8000, 16000, 22050, 24000, 32000, 44100, 48000, 88200, 96000]
    sr_val = rng.choice(rate_choices) & 0xFF

    sample_size_bits = rng.choice([8, 16, 24, 32])
    channels = rng.choice([1, 2, 4])

    # Simple channel maps for 1/2/4 channels
    ch_map_options = {
        1: [0x0001],
        2: [0x0003, 0x0009],
        4: [0x000F, 0x0033]
    }
    channel_map = rng.choice(ch_map_options.get(channels, [0x0003]))

    # Producer indices
    write_idx = rng.randrange(0, max_chunks)
    # Offset within ring; keep less than max_chunks
    offset = rng.randrange(0, max(1, min(8, max_chunks)))

    # Magic number: pick from a few recognizable constants
    magic = rng.choice([0x53484D31, 0xDEADBEEF, 0xC0DEC0DE, 0x41445531])  # 'SHM1', DEADBEEF, C0DEC0DE, 'ADU1'

    header = _pack_header_le(magic, write_idx, offset, max_chunks, chunk_size,
                             sr_val, sample_size_bits, channels, channel_map)

    # Generate chunked data. Fill with patterns to exercise code paths: zeros, ramp, noise, silence+peaks.
    chunks: List[bytes] = []

    def make_zero(n: int) -> bytes:
        return b"\x00" * n

    def make_ramp(n: int) -> bytes:
        return bytes((i & 0xFF for i in range(n)))

    def make_noise(n: int) -> bytes:
        return bytes(rng.getrandbits(8) for _ in range(n))

    def make_alt(n: int) -> bytes:
        return (b"\xFF\x00" * (n // 2)) + (b"\xFF" if n % 2 else b"")

    patterns = [make_zero, make_ramp, make_noise, make_alt]

    # Build each chunk with a randomly chosen pattern; ensure at least one non-zero chunk
    non_zero_present = False
    for _ in range(max_chunks):
        pattern = rng.choice(patterns)
        data = pattern(chunk_size)
        if any(b != 0 for b in data[:32]):
            non_zero_present = True
        chunks.append(data)

    if not non_zero_present and chunks:
        chunks[0] = make_ramp(chunk_size)

    body = b"".join(chunks)
    return header + body


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Randomly choose among a few valid file variants:
    variant = rng.randrange(0, 5)

    if variant == 0:
        rng2 = random.Random(rng.getrandbits(64))
        buf = _generate_valid_shm_file(rng2)
    elif variant == 1:
        # Emphasize stereo 16-bit with medium chunks where possible
        rng2 = random.Random(rng.getrandbits(64))
        for _ in range(10):
            buf = _generate_valid_shm_file(rng2)
            hdr = struct.unpack('<IHBHI BBBH'.replace(' ', ''), buf[:18])
            _, _, _, _, chunk_size, _, ss, ch, _ = hdr
            if (ss == 16 and ch == 2 and chunk_size in (128, 256, 512)):
                break
    elif variant == 2:
        # Larger buffer within limit
        rng2 = random.Random(rng.getrandbits(64))
        for _ in range(20):
            buf = _generate_valid_shm_file(rng2)
            if len(buf) > 2048:
                break
    elif variant == 3:
        # All-zero chunks to simulate silence
        rng2 = random.Random(rng.getrandbits(64))
        base = _generate_valid_shm_file(rng2)
        header = base[:18]
        body_len = len(base) - 18
        buf = header + (b"\x00" * body_len)
    else:
        rng2 = random.Random(rng.getrandbits(64))
        buf = _generate_valid_shm_file(rng2)

    return buf[:4096]
